import AppKit
import SwiftUI
import Observation

// Machine, ModelInfo, MachineStatus and the other types from the Rust core are
// generated by UniFFI into Generated/snow_ffi.swift.

extension ModelInfo: Identifiable {
    public var id: UInt32 { index }

    static let all = models()

    static func named(_ index: UInt32?) -> ModelInfo? {
        all.first { $0.index == index }
    }

    static func detect(romPath: String) -> ModelInfo? {
        romPath.isEmpty ? nil : named(detectModel(romPath: romPath))
    }

    /// The models a ROM runs in, the one it's detected as first. Read once per ROM.
    @MainActor
    static func compatible(withROM romPath: String) -> [ModelInfo] {
        guard !romPath.isEmpty else { return [] }
        if let models = compatibleCache[romPath] { return models }
        let models = modelsForRom(romPath: romPath).compactMap(named)
        compatibleCache[romPath] = models
        return models
    }

    @MainActor private static var compatibleCache: [String: [ModelInfo]] = [:]

    /// The least video memory the model can have, for models where it can be
    /// chosen. New machines start with it: without a size, the core uses its own
    /// default, often more.
    var lowestVRAMSize: UInt64? {
        defaultVramSize == nil ? nil : vramSizes.min()
    }
}

/// A model's symbol: the custom SF Symbol in the asset catalog of its case, which
/// models with the same case share, or a generic computer for a model without one,
/// or an unknown model
struct ModelSymbol: View {
    /// The model's identifier, like "Early128K"
    let identifier: String?

    var body: some View {
        Group {
            if let name = identifier.flatMap(Self.symbolName), Self.exists(name) {
                Image(name)
            } else {
                Image(systemName: "desktopcomputer")
            }
        }
        .symbolRenderingMode(.hierarchical)
    }

    /// The symbol of a model's case, or nil if there isn't one for it
    static func symbolName(of identifier: String) -> String? {
        switch identifier {
        case "Early128K", "Early512K", "Early512Ke": "mac.128k"
        case "Plus": "mac.plus"
        case "SE", "SeFdhd": "mac.se"
        case "SE30": "mac.se30"
        case "Classic": "mac.classic"
        case "MacII", "MacIIFDHD", "MacIIx": "mac.ii"
        case "MacIIcx": "mac.iicx"
        case "LC", "LCII", "LCIII", "LC475": "mac.lc"
        case "Quadra700": "mac.quadra700"
        case "Portable": "laptopcomputer"
        default: nil
        }
    }

    @MainActor private static var known: [String: Bool] = [:]

    @MainActor private static func exists(_ name: String) -> Bool {
        if let exists = known[name] { return exists }
        let exists = NSImage(symbolName: name, bundle: .main, variableValue: 1) != nil
            || NSImage(named: name) != nil
        known[name] = exists
        return exists
    }
}

extension ModelSpecs {
    /// Like "15.67 MHz"
    var cpuSpeed: String {
        "\(cpuMhz.formatted(.number.precision(.fractionLength(0...2)))) MHz"
    }

    /// Like "2 × 800K", or "800K" for a single drive
    var floppies: String {
        floppyDrives == 1 ? floppyKind.label : "\(floppyDrives) × \(floppyKind.label)"
    }

    /// The internal hard disk's size in bytes, or nil if the base model had none
    var hardDiskSize: UInt64? {
        hardDiskMb.map { UInt64($0) * 1024 * 1024 }
    }
}

extension ModelSpecs {
    /// Like "All-in-one, 1984"
    var formFactorAndYear: String {
        "\(formFactor.label), \(releaseYear)"
    }
}

extension FormFactor {
    var label: String {
        switch self {
        case .allInOne: "All-in-one"
        case .desktop: "Desktop"
        case .portable: "Portable"
        }
    }
}

extension FloppyKind {
    var label: String {
        switch self {
        case .gcr400k: "400K"
        case .gcr800k: "800K"
        case .superDrive: "1.4MB SuperDrive"
        }
    }
}

extension VideoSettings {
    /// For a machine whose workspace can't be read
    static let standard = VideoSettings(
        scaling: true, integerScaling: false, physicalSize: false, scalingAlgorithm: .nearestNeighbor,
        crtEffect: false)
}

extension ScalingAlgorithm: Identifiable {
    public var id: Self { self }

    static let allCases: [ScalingAlgorithm] = [.linear, .nearestNeighbor]

    var label: String {
        switch self {
        case .linear: "Smooth"
        case .nearestNeighbor: "Sharp"
        }
    }
}

extension FloppyStatus: Identifiable {
    public var id: UInt32 { drive }
}

extension EmulationSpeed: Identifiable {
    public var id: Self { self }

    static let allCases: [EmulationSpeed] = [.accurate, .dynamic, .uncapped, .video]

    var label: String {
        switch self {
        case .accurate: "Accurate"
        case .dynamic: "Dynamic"
        case .uncapped: "Uncapped"
        case .video: "Sync to Video"
        }
    }
}

extension Monitor: Identifiable {
    public var id: Self { self }

    private var info: MonitorInfo { monitorInfo(monitor: self) }

    var name: String { info.name }
    /// Like "640 × 480"
    var resolution: String { "\(info.width) × \(info.height)" }

    /// Its symbol in the asset catalog
    var symbolName: String {
        switch self {
        case .rgb12: "monitor.rgb12"
        case .hiRes14: "monitor.hiresrgb"
        case .rgb16: "monitor.rgb16"
        case .rgb21: "monitor.rgb21"
        case .portraitBw: "monitor.portraitbw"
        case .twoPageBw: "monitor.twopagebw"
        case .vga: "monitor.vga"
        }
    }
}

extension DisplayCard: Identifiable {
    public var id: Self { self }

    static let allCases: [DisplayCard] = [.mdc824, .toby]

    var label: String {
        switch self {
        case .mdc824: "Macintosh Display Card 8•24"
        case .toby: "Macintosh II Video Card"
        }
    }
}

/// Switching from one machine to another. What the window showed of the one switched
/// from, kept on show until the other is ready.
struct MachineSwitch {
    let from: MachineEntry?
    let to: MachineEntry?
    /// Its screen was on show, rather than the view to start it
    let showsScreen: Bool
    let video: VideoSettings
    let crtParameters: [Float]?
    let screenPixelsPerInch: Double?
}

/// A message from the emulator, as shown in the banner or an alert
struct UserMessage: Identifiable, Equatable {
    let id = UUID()
    let kind: MessageKind
    let text: String
}

/// The selected machine and the state of its emulator, as shown by the UI.
///
/// Only the selected machine runs. Switching to another one suspends it: its state is
/// saved in its folder, and it resumes from there when selected again, or at the next
/// launch.
@MainActor
@Observable
final class EmulatorModel {
    let library = MachineLibrary()

    /// The running emulator. Releasing it stops the emulator thread.
    private var machine: Machine?
    /// Where the running emulator keeps its disks, if it was resumed from a state
    private var machineTempDir: URL?

    /// The machine selected in the sidebar
    private(set) var current: MachineEntry?
    /// Switching to another machine: the one switched from stays on show, as it was,
    /// until the other is ready
    private(set) var switching: MachineSwitch?
    /// What's being done while the machine is saved, restored or started
    private(set) var busyMessage: String?
    /// The machine being saved or shut down. It counts as on until it's done.
    private(set) var stoppingID: MachineEntry.ID?
    /// The sheet for setting up a new machine is open
    var showsNewMachine = false
    /// The inspector with the selected machine's settings is open
    /// Starts closed, and closes when another machine is selected
    var showsInspector = false

    /// How the selected machine's display is shown
    private(set) var video = VideoSettings.standard
    /// The settings of the CRT effect that suit the selected machine's screen, or nil
    /// if its screen isn't a CRT
    private(set) var crtParameters: [Float]?
    /// How many of the selected machine's screen's pixels there were to the inch, or
    /// nil if it isn't known
    private(set) var screenPixelsPerInch: Double?
    /// The selected machine's screen: its monitor or built-in display
    private(set) var screen: ScreenInfo?
    /// Writes changed video settings once they settle, so dragging a slider doesn't
    /// write the workspace over and over
    @ObservationIgnored private var videoSave: Task<Void, Never>?

    private(set) var isRunning = false
    private(set) var speedPercent = 0
    private(set) var speed = EmulationSpeed.accurate
    /// Whether the machines' sound is muted. Kept across launches, for every machine.
    var isMuted = UserDefaults.standard.bool(forKey: "muted") {
        didSet {
            UserDefaults.standard.set(isMuted, forKey: "muted")
            machine?.setMuted(muted: isMuted)
        }
    }
    private(set) var floppies: [FloppyStatus] = []
    /// The CD-ROM drives the machine has, by SCSI ID
    private(set) var cdroms: [CdromStatus] = []
    /// The machine's model can have CD-ROM drives
    private(set) var hasSCSI = false

    /// The CD-ROM drives to offer, with their names, for a model that can have
    /// them. Without any, it's the one inserting a disc adds, as nil.
    var cdromDrives: [(title: String, drive: CdromStatus?)] {
        guard isActive, hasSCSI else { return [] }
        if cdroms.isEmpty { return [("CD-ROM", nil)] }
        return cdroms.enumerated().map { index, drive in
            (cdroms.count == 1 ? "CD-ROM" : "CD-ROM \(index + 1)", drive)
        }
    }
    /// Counts the changes to the current machine's drives made while it runs, when
    /// the guest ejects a disc or one is dropped onto it, so views showing its
    /// settings can reload the drives that changed
    private(set) var driveChanges = 0
    /// The latest message from the emulator, shown for a moment
    private(set) var banner: UserMessage?
    /// An error to show in an alert
    var alert: UserMessage?

    @ObservationIgnored private var lastSpeedUpdate = Date.distantPast
    /// The CPU cycle count at the last speed update, to measure the speed from
    @ObservationIgnored private var lastSpeedCycles: UInt64?

    private static let lastMachineKey = "lastMachine"
    /// Where earlier versions kept whether the inspector was open
    private static let oldShowsInspectorKey = "showsInspector"

    var isActive: Bool { machine != nil }
    /// The machine the window shows: while switching, the one switched from, or the
    /// one switched to when there was none, as when the app resumes a machine at
    /// launch
    var displayedEntry: MachineEntry? {
        if let switching { switching.from ?? switching.to } else { current }
    }
    /// The machine selected in the sidebar: while switching, the one switched to
    var selectedEntry: MachineEntry? {
        if let switching { switching.to } else { current }
    }
    var isBusy: Bool { busyMessage != nil }

    /// - Parameter restoringSession: selects the machine selected when the app last
    ///   quit, and resumes it. Previews pass false, so they don't start an emulator.
    init(restoringSession: Bool = true) {
        UserDefaults.standard.removeObject(forKey: Self.oldShowsInspectorKey)
        // Pick up where the last session left off. A machine is always selected
        // while there is one, so without the last one it's the first.
        if restoringSession,
            let entry = UserDefaults.standard.string(forKey: Self.lastMachineKey)
                .flatMap(library.entry(named:)) ?? library.machines.first
        {
            // Shown from the first frame, so the window doesn't show no machine
            // before it starts
            switching = MachineSwitch(
                from: nil, to: entry, showsScreen: false, video: video, crtParameters: nil,
                screenPixelsPerInch: nil)
            Task { await select(entry) }
        } else if restoringSession, library.machines.isEmpty {
            // The first launch, or all machines are gone: set one up
            showsNewMachine = true
        }
    }

    #if DEBUG
    /// For previews: shows a machine as selected, without starting it
    convenience init(previewing entry: MachineEntry) {
        self.init(restoringSession: false)
        current = entry
        video = videoSettings(of: entry)
        let screen = try? workspaceScreen(path: entry.workspaceURL.filePath)
        crtParameters = screen?.crtParameters
        screenPixelsPerInch = screen?.pixelsPerInch
        self.screen = screen
    }
    #endif

    // MARK: Switching machines

    /// Suspends the running machine, then selects another one and resumes it if
    /// it has a saved state
    func select(_ entry: MachineEntry?) async {
        guard !isBusy, entry?.id != current?.id else { return }
        showsInspector = false
        switching = MachineSwitch(
            from: current, to: entry, showsScreen: isActive, video: video,
            crtParameters: video.crtEffect ? crtParameters : nil,
            screenPixelsPerInch: screenPixelsPerInch)
        defer { switching = nil }
        await suspend()
        setCurrent(entry)
        if let entry, entry.hasSavedState {
            await resume()
        }
    }

    /// Saves the state of the running machine and stops it
    func suspend() async {
        guard let current, machine != nil else { return }
        await stopMachine(message: "Saving “\(current.name)”…", saveState: true)
    }

    /// Powers the running machine off without saving its state
    func powerOff() async {
        guard let current, machine != nil else { return }
        await stopMachine(message: "Shutting down “\(current.name)”…", saveState: false)
        discardSavedState(of: current)
    }

    /// Resumes the selected machine from its saved state
    func resume() async {
        guard let current, machine == nil, !isBusy else { return }
        let tempDir = FileManager.default.temporaryDirectory
            .appending(path: "Snow", directoryHint: .isDirectory)
            .appending(path: UUID().uuidString, directoryHint: .isDirectory)
        let state = current.stateURL.filePath
        let workspace = current.workspaceURL.filePath
        await startMachine(message: "Restoring “\(current.name)”…", tempDir: tempDir) {
            try Machine.resume(statePath: state, workspacePath: workspace, tempDir: tempDir.filePath)
        } failure: { message in
            "“\(current.name)” could not be restored from its saved state: \(message)\n\nYou can start it fresh instead."
        }
    }

    /// Starts the selected machine from scratch, discarding a saved state
    func startFresh() async {
        guard let current, !isBusy else { return }
        await powerOff()
        discardSavedState(of: current)
        let workspace = current.workspaceURL.filePath
        await startMachine(message: "Starting “\(current.name)”…", tempDir: nil) {
            try Machine.fromWorkspace(workspacePath: workspace)
        } failure: { message in
            "“\(current.name)” could not be started: \(message)"
        }
    }

    /// Waits for whatever is being done to finish, then suspends. For quitting.
    func suspendForQuit() async {
        saveVideoNow()
        while isBusy {
            try? await Task.sleep(for: .milliseconds(50))
        }
        await suspend()
    }

    private func stopMachine(message: String, saveState: Bool) async {
        guard let machine, let current else { return }
        busyMessage = message
        stoppingID = current.id
        defer { stoppingID = nil }
        clearMachine()
        let statePath = saveState ? current.stateURL.filePath : nil
        do {
            try await Task.detached { try machine.powerOff(statePath: statePath) }.value
            if let machineTempDir {
                try? FileManager.default.removeItem(at: machineTempDir)
            }
        } catch {
            // A disk that couldn't be written back is left in the temporary directory
            showError("“\(current.name)” didn't shut down cleanly: \(Self.describe(error))")
        }
        machineTempDir = nil
        refreshCurrent()
        busyMessage = nil
    }

    private func startMachine(
        message: String, tempDir: URL?, _ make: @escaping @Sendable () throws -> Machine,
        failure: (String) -> String
    ) async {
        busyMessage = message
        do {
            machine = try await Task.detached(operation: make).value
            machine?.setMuted(muted: isMuted)
            machineTempDir = tempDir
            tick()
        } catch {
            if let tempDir {
                try? FileManager.default.removeItem(at: tempDir)
            }
            showError(failure(Self.describe(error)))
        }
        busyMessage = nil
    }

    private func clearMachine() {
        machine = nil
        lastFrame = nil
        lastSpeedCycles = nil
        isRunning = false
        speedPercent = 0
        // Not a change of speed to save: the next machine reports its own
        speed = .accurate
        speedBeforeFastForward = nil
        floppies = []
        cdroms = []
        hasSCSI = false
    }

    private func setCurrent(_ entry: MachineEntry?) {
        if entry?.id != current?.id {
            saveVideoNow()
            video = entry.map(videoSettings(of:)) ?? .standard
        }
        // Its monitor may have changed
        let screen = entry.flatMap { try? workspaceScreen(path: $0.workspaceURL.filePath) }
        crtParameters = screen?.crtParameters
        screenPixelsPerInch = screen?.pixelsPerInch
        self.screen = screen
        current = entry
        UserDefaults.standard.set(entry?.name, forKey: Self.lastMachineKey)
    }

    private func refreshCurrent() {
        if let current {
            setCurrent(library.refreshed(current))
        }
    }

    // MARK: Managing machines

    func create(_ setup: MachineSetup, newDiskSize: UInt64? = nil) async {
        guard !isBusy else { return }
        await suspend()
        do {
            setCurrent(try library.create(setup, newDiskSize: newDiskSize))
            await startFresh()
        } catch {
            showError("The Macintosh could not be created: \(Self.describe(error))")
        }
    }

    /// Whether changing the machine's hardware would discard its state: it's running,
    /// or suspended
    func isInUse(_ entry: MachineEntry) -> Bool {
        entry.hasSavedState || (entry.id == current?.id && isActive)
    }

    /// Saves new hardware settings. A saved state no longer matches them, so it's
    /// discarded and a running machine starts again. Returns the settings as saved,
    /// with the paths of the ROMs' copies in the machine's folder, or nil if they
    /// weren't saved.
    @discardableResult
    func update(_ entry: MachineEntry, with setup: MachineSetup) async -> MachineSetup? {
        guard !isBusy else { return nil }
        let wasActive = entry.id == current?.id && isActive
        if wasActive {
            await powerOff()
        }
        do {
            let (saved, stored) = try library.update(entry, with: setup)
            let updated = try library.discardSavedState(of: saved)
            if entry.id == current?.id {
                setCurrent(updated)
                if wasActive {
                    await startFresh()
                }
            }
            return stored
        } catch {
            showError("The settings could not be saved: \(Self.describe(error))")
            return nil
        }
    }

    /// Saves settings that don't change the hardware, keeping the machine running or
    /// suspended. They take effect the next time it starts. Returns the settings as
    /// saved, or nil if they weren't saved.
    @discardableResult
    func saveSettings(_ entry: MachineEntry, _ setup: MachineSetup) -> MachineSetup? {
        do {
            let (updated, stored) = try library.update(entry, with: setup)
            if entry.id == current?.id {
                setCurrent(updated)
            }
            return stored
        } catch {
            showError("The settings could not be saved: \(Self.describe(error))")
            return nil
        }
    }

    /// Selects the machine and opens the inspector with its settings
    func showSettings(of entry: MachineEntry) async {
        await select(entry)
        if current?.id == entry.id {
            showsInspector = true
        }
    }

    /// Returns the renamed machine, or nil if it couldn't be renamed
    @discardableResult
    func rename(_ entry: MachineEntry, to name: String) -> MachineEntry? {
        // The settings are written to the workspace where it is now
        if entry.id == current?.id {
            saveVideoNow()
        }
        do {
            let renamed = try library.rename(entry, to: name)
            if entry.id == current?.id {
                setCurrent(renamed)
            }
            return renamed
        } catch {
            showError("The Macintosh could not be renamed: \(Self.describe(error))")
            return nil
        }
    }

    func delete(_ entry: MachineEntry) async {
        guard !isBusy else { return }
        let isCurrent = entry.id == current?.id
        // A machine stays selected while there is one: the one after it in the list,
        // or before it if it was last. It isn't resumed.
        let machines = library.machines
        let neighbor = machines.firstIndex { $0.id == entry.id }.flatMap { index in
            machines.indices.contains(index + 1) ? machines[index + 1]
                : index > 0 ? machines[index - 1] : nil
        }
        if isCurrent {
            await powerOff()
        }
        do {
            try library.delete(entry)
        } catch {
            showError("The Macintosh could not be moved to the Trash: \(Self.describe(error))")
            return
        }
        if isCurrent {
            setCurrent(neighbor.flatMap { library.entry($0.id) })
        }
    }

    func discardSavedState(of entry: MachineEntry) {
        do {
            let updated = try library.discardSavedState(of: entry)
            if entry.id == current?.id {
                setCurrent(updated)
            }
        } catch {
            showError("The saved state could not be deleted: \(Self.describe(error))")
        }
    }

    func importWorkspace(from url: URL) async {
        guard !isBusy else { return }
        do {
            let entry = try library.importWorkspace(from: url)
            await select(entry)
        } catch {
            showError("The workspace could not be imported: \(Self.describe(error))")
        }
    }

    func setup(of entry: MachineEntry) -> MachineSetup? {
        do {
            return try library.setup(of: entry)
        } catch {
            showError("The settings could not be read: \(Self.describe(error))")
            return nil
        }
    }

    // MARK: Video

    /// Changes how the selected machine's display is shown. The screen shows the
    /// change at once; it's saved to the machine's workspace shortly after.
    func setVideo(_ settings: VideoSettings) {
        guard current != nil, settings != video else { return }
        video = settings
        videoSave?.cancel()
        videoSave = Task { [weak self] in
            try? await Task.sleep(for: .milliseconds(500))
            guard !Task.isCancelled else { return }
            self?.saveVideoNow()
        }
    }

    /// Writes video settings that are waiting to be saved
    private func saveVideoNow() {
        guard let videoSave else { return }
        videoSave.cancel()
        self.videoSave = nil
        guard let current else { return }
        do {
            try writeVideoSettings(path: current.workspaceURL.filePath, settings: video)
        } catch {
            showError("The video settings could not be saved: \(Self.describe(error))")
        }
    }

    private func videoSettings(of entry: MachineEntry) -> VideoSettings {
        (try? readVideoSettings(path: entry.workspaceURL.filePath)) ?? .standard
    }

    // MARK: Commands

    func togglePause() {
        isRunning ? machine?.stop() : machine?.run()
    }

    func reset() { machine?.reset() }

    func programmerKey() { machine?.programmerKey() }

    func setSpeed(_ speed: EmulationSpeed) { machine?.setSpeed(speed: speed) }

    /// Whether the machine is fast-forwarding: running at dynamic speed (as fast as
    /// it can, except while it plays sound), or uncapped
    var isFastForwarding: Bool { speed == .dynamic || speed == .uncapped }

    /// Saves whether the machine is fast-forwarding, so it starts the same way the
    /// next time, as it was when it last ran
    private func saveFastForward() {
        guard let current else { return }
        do {
            try writeWorkspaceFastForward(
                path: current.workspaceURL.filePath, fastForward: isFastForwarding)
        } catch {
            show(UserMessage(
                kind: .warning,
                text: "Fast-forwarding could not be saved: \(Self.describe(error))"))
        }
    }

    /// The speed fast-forwarding was turned on from, to go back to
    @ObservationIgnored private var speedBeforeFastForward: EmulationSpeed?

    /// Fast-forwards the machine at dynamic speed, or goes back to the speed it ran
    /// at before. A machine that started fast-forwarding goes back to accurate speed.
    func toggleFastForward() {
        if isFastForwarding {
            setSpeed(speedBeforeFastForward ?? .accurate)
            speedBeforeFastForward = nil
        } else {
            speedBeforeFastForward = speed
            setSpeed(.dynamic)
        }
    }

    func insertFloppy(drive: UInt32, url: URL) {
        machine?.insertFloppy(drive: drive, path: url.filePath, writeProtect: false)
    }

    /// Makes the changes that a running machine takes as it runs: the discs chosen
    /// for its CD-ROM drives go in, and its Ethernet link changes. A disc taken out
    /// of the settings stays in the drive until the guest ejects it.
    func applyLiveChanges(of entry: MachineEntry, from old: MachineSetup, to new: MachineSetup) {
        guard entry.id == current?.id, let machine else { return }
        if new.ethernetLink != old.ethernetLink {
            machine.setEthernetLink(link: new.ethernetLink)
        }
        for id in new.scsi.indices {
            guard case .cdrom(let disc?) = new.scsi[id], case .cdrom(let oldDisc) = old.scsi[id],
                disc != oldDisc
            else { continue }
            machine.insertDisc(id: UInt32(id), disc: disc)
        }
    }

    /// Puts files dropped onto the machine in its drives: floppy images in its
    /// floppy drives, and CD-ROM images in a CD-ROM drive. Returns false if none
    /// went in.
    @discardableResult
    func insertDroppedImages(_ urls: [URL]) -> Bool {
        guard machine != nil else { return false }
        // Drives filled by this drop, which the status doesn't show yet
        var filled = Set<UInt32>()
        var filledCDROMs = Set<Int>()
        var inserted = false
        for url in urls {
            switch diskImageKind(path: url.filePath) {
            case .floppy:
                if let drive = insertFloppyInFreeDrive(url: url, filled: filled) {
                    filled.insert(drive)
                    inserted = true
                }
            case .cdrom:
                if let id = insertDroppedDisc(url: url, filled: filledCDROMs) {
                    filledCDROMs.insert(id)
                    inserted = true
                }
            case nil:
                show(UserMessage(
                    kind: .warning,
                    text: "\u{201C}\(url.lastPathComponent)\u{201D} isn't a floppy disk or CD-ROM image"))
            }
        }
        return inserted
    }

    /// Inserts a floppy disk into the first drive without one. Returns the drive, or
    /// nil if every drive has a disk.
    private func insertFloppyInFreeDrive(url: URL, filled: Set<UInt32>) -> UInt32? {
        let drives = floppies.filter(\.present)
        guard let free = drives.first(where: { !$0.inserted && !filled.contains($0.drive) }) else {
            show(UserMessage(
                kind: .warning,
                text: drives.isEmpty
                    ? "This Macintosh has no floppy drive"
                    : "There's no empty floppy drive. Eject a disk first."))
            return nil
        }
        insertFloppy(drive: free.drive, url: url)
        return free.drive
    }

    /// Inserts a disc into the first empty CD-ROM drive. Without a CD-ROM drive, it
    /// adds one. Returns the drive's SCSI ID, or nil if the disc didn't go in.
    ///
    /// - Parameter filled: the drives earlier files of the same drop went into,
    ///   which the status doesn't show yet
    private func insertDroppedDisc(url: URL, filled: Set<Int>) -> Int? {
        let drives = cdroms.filter { $0.managedFolder == nil }
        if let empty = drives.first(where: { $0.discPath == nil && !filled.contains(Int($0.id)) }) {
            return insertDisc(.image(path: url.filePath), drive: Int(empty.id))
        }
        guard drives.isEmpty, filled.isEmpty else {
            show(UserMessage(kind: .warning, text: "There's no empty CD-ROM drive. Eject the disc first."))
            return nil
        }
        return insertDisc(.image(path: url.filePath), drive: nil)
    }

    /// Inserts a disc into the CD-ROM drive at a SCSI ID, or with nil, into a new
    /// drive added while the machine runs. The disc and drive are saved in the
    /// machine's settings, as when chosen in the inspector. Returns the drive's
    /// SCSI ID, or nil if the disc didn't go in.
    @discardableResult
    func insertDisc(_ disc: CdromDisc, drive: Int?) -> Int? {
        guard let entry = current, let machine, var setup = self.setup(of: entry) else {
            return nil
        }
        let id: Int
        if let drive {
            id = drive
            machine.insertDisc(id: UInt32(id), disc: disc)
        } else if let free = setup.freeCDROMID {
            id = free
            machine.attachCdrom(id: UInt32(id), disc: disc)
        } else {
            show(UserMessage(kind: .warning, text: "There's no free SCSI ID for a CD-ROM drive"))
            return nil
        }
        guard setup.scsi.indices.contains(id) else { return id }
        setup.scsi[id] = .cdrom(disc: disc)
        do {
            setCurrent(try library.update(entry, with: setup).entry)
            driveChanges += 1
        } catch {
            showError("The inserted disc could not be saved: \(Self.describe(error))")
        }
        return id
    }

    func ejectFloppy(drive: UInt32) { machine?.ejectFloppy(drive: drive) }

    func exportState(to url: URL) { machine?.exportState(path: url.filePath) }

    // MARK: Input

    func key(_ scancode: UInt8, down: Bool) {
        guard isRunning else { return }
        machine?.key(scancode: scancode, down: down)
    }

    func mouseMoved(to point: CGPoint) {
        guard isRunning else { return }
        machine?.mouseAbsolute(x: UInt16(point.x), y: UInt16(point.y))
    }

    func mouseButton(down: Bool) {
        guard isRunning else { return }
        machine?.mouseButton(down: down)
    }

    func releaseAllInputs() { machine?.releaseAllInputs() }

    // MARK: Polling

    /// Picks up what the emulator reported. Called once per displayed frame.
    func tick() {
        guard let machine else { return }

        for message in machine.takeMessages() {
            let message = UserMessage(kind: message.kind, text: message.text)
            if message.kind == .error {
                alert = message
            } else {
                show(message)
            }
        }

        let ejected = machine.takeEjectedDiscs()
        if !ejected.isEmpty {
            discsEjected(at: ejected.map(Int.init))
        }

        guard machine.isAlive() else {
            handleCrash()
            return
        }
        guard let status = machine.status() else { return }

        update(\.isRunning, status.running)
        if status.speed != speed {
            let wasFastForwarding = isFastForwarding
            speed = status.speed
            if isFastForwarding != wasFastForwarding {
                saveFastForward()
            }
        }
        update(\.floppies, status.floppies)
        update(\.cdroms, status.cdroms)
        update(\.hasSCSI, ModelInfo.named(status.model)?.hasScsi == true)
        // The speed changes all the time; redraw it only twice a second
        let now = Date.now
        let elapsed = now.timeIntervalSince(lastSpeedUpdate)
        if elapsed > 0.5 {
            update(\.speedPercent, status.running ? measuredSpeedPercent(status, over: elapsed) : 0)
            lastSpeedUpdate = now
            lastSpeedCycles = status.cycles
        }
    }

    /// The guest ejected discs: their drives are saved empty, as they now are, so the
    /// discs don't go back in when the machine resumes
    private func discsEjected(at ids: [Int]) {
        guard let entry = current, var setup = try? library.setup(of: entry) else { return }
        var changed = false
        for id in ids where setup.scsi.indices.contains(id) {
            if case .cdrom(_?) = setup.scsi[id] {
                setup.scsi[id] = .cdrom(disc: nil)
                changed = true
            }
        }
        guard changed else { return }
        do {
            setCurrent(try library.update(entry, with: setup).entry)
            driveChanges += 1
        } catch {
            showError("The ejected disc could not be saved: \(Self.describe(error))")
        }
    }

    /// The speed over the last moments, from the CPU cycles run against the model's
    /// clock. The core's own measure is smoothed over many seconds, so it takes
    /// half a minute to come back to 100% after fast-forwarding; this follows a
    /// change of speed at once. Without a measurement yet, it's the core's.
    private func measuredSpeedPercent(_ status: MachineStatus, over elapsed: TimeInterval) -> Int {
        let core = Int((status.effectiveSpeed * 100).rounded())
        guard let lastSpeedCycles, status.cycles >= lastSpeedCycles, elapsed < 2,
              let mhz = ModelInfo.named(status.model)?.specs.cpuMhz, mhz > 0
        else { return core }
        let hertz = Double(status.cycles - lastSpeedCycles) / elapsed
        return Int((hertz / (mhz * 1_000_000) * 100).rounded())
    }

    /// Takes the newest frame, if there is one that hasn't been shown yet
    func takeFrame() -> Frame? {
        let frame = machine?.takeFrame()
        if let frame { lastFrame = frame }
        return frame
    }

    /// The frame shown last, for screenshots
    @ObservationIgnored private var lastFrame: Frame?

    /// Saves the screen as shown last to the Desktop, as a PNG image named as the
    /// egui frontend names its screenshots
    func takeScreenshot() {
        guard let frame = lastFrame, let image = Self.image(of: frame) else {
            showError("There's nothing on the screen to take a screenshot of yet.")
            return
        }
        let desktop = FileManager.default.urls(for: .desktopDirectory, in: .userDomainMask).first
            ?? URL(filePath: FileManager.default.currentDirectoryPath)
        let date = Date.now.formatted(
            .verbatim(
                "\(year: .defaultDigits)-\(month: .twoDigits)-\(day: .twoDigits) \(hour: .twoDigits(clock: .twentyFourHour, hourCycle: .zeroBased))-\(minute: .twoDigits)-\(second: .twoDigits)",
                timeZone: .current, calendar: .current))
        let name = "Snow screenshot \(date).png"
        let png = NSBitmapImageRep(cgImage: image).representation(using: .png, properties: [:])
        do {
            guard let png else { throw CocoaError(.fileWriteUnknown) }
            try png.write(to: desktop.appending(path: name), options: .withoutOverwriting)
            show(UserMessage(kind: .success, text: "Saved screenshot to the Desktop as \u{201C}\(name)\u{201D}"))
        } catch {
            showError("The screenshot could not be saved. \(error.localizedDescription)")
        }
    }

    private static func image(of frame: Frame) -> CGImage? {
        let width = Int(frame.width), height = Int(frame.height)
        guard width > 0, height > 0, frame.pixels.count >= width * height * 4,
              let provider = CGDataProvider(data: Data(frame.pixels) as CFData)
        else { return nil }
        return CGImage(
            width: width, height: height, bitsPerComponent: 8, bitsPerPixel: 32,
            bytesPerRow: width * 4, space: CGColorSpace(name: CGColorSpace.sRGB)!,
            bitmapInfo: CGBitmapInfo(rawValue: CGImageAlphaInfo.noneSkipLast.rawValue),
            provider: provider, decode: nil, shouldInterpolate: false, intent: .defaultIntent)
    }

    /// The emulator thread stopped on its own. Shut down properly so the disks are
    /// written back; the saved state would no longer match them, so it goes too.
    private func handleCrash() {
        guard !isBusy else { return }
        // Keeps further frames from coming here until the shutdown starts
        busyMessage = "Shutting down…"
        showError("The emulator stopped unexpectedly. See the log for details.")
        Task {
            busyMessage = nil
            await powerOff()
        }
    }

    // MARK: Helpers

    /// Sets a property only when it changes, so SwiftUI doesn't redraw every frame
    private func update<T: Equatable>(_ keyPath: ReferenceWritableKeyPath<EmulatorModel, T>, _ value: T) {
        if self[keyPath: keyPath] != value {
            self[keyPath: keyPath] = value
        }
    }

    private func showError(_ text: String) {
        alert = UserMessage(kind: .error, text: text)
    }

    private static func describe(_ error: Error) -> String {
        if case let SnowError.Failed(message) = error {
            return message
        }
        return error.localizedDescription
    }

    private func show(_ message: UserMessage) {
        banner = message
        Task { [weak self] in
            try? await Task.sleep(for: .seconds(4))
            if self?.banner == message {
                self?.banner = nil
            }
        }
    }
}
